<?= $this->extend(PATIENT_VIEW . 'layout') ?>

<?= $this->section('main-content') ?>
<main class="patient-page patient-notifications-page" aria-labelledby="patient-notifications-title">
    <header class="patient-page-heading">
        <div><span class="patient-eyebrow">Patient portal / updates</span><h1 id="patient-notifications-title">Notifications</h1><p class="text-muted mb-0">Clinic-scoped updates related to your care and orders.</p></div>
        <span class="badge badge-primary"><i class="bi bi-bell mr-1" aria-hidden="true"></i><span id="patient-unread-count"><?= (int) $unread ?></span> unread</span>
    </header>
    <section class="card patient-list-toolbar" aria-label="Notification filters"><form method="get" action="<?= current_url() ?>" class="patient-filter-form"><div class="patient-filter-search"><label class="sr-only" for="patient-notification-search">Search notifications</label><i class="bi bi-search" aria-hidden="true"></i><input id="patient-notification-search" class="form-control" type="search" name="search" value="<?= esc($filters['search']) ?>" placeholder="Title, message, type or related reference"></div><select class="form-control form-control-sm" name="status" aria-label="Read status"><option value="">All notifications</option><option value="unread" <?= $filters['status'] === 'unread' ? 'selected' : '' ?>>Unread</option><option value="read" <?= $filters['status'] === 'read' ? 'selected' : '' ?>>Read</option></select><select class="form-control form-control-sm" name="type" aria-label="Notification type"><option value="">All types</option><?php foreach ($types as $type): ?><option value="<?= esc($type['related_entity_type'] ?? '') ?>" <?= $filters['type'] === ($type['related_entity_type'] ?? '') ? 'selected' : '' ?>><?= esc(ucwords(str_replace('_', ' ', $type['related_entity_type'] ?? 'Notification'))) ?></option><?php endforeach; ?></select><input class="form-control form-control-sm patient-date-filter" type="text" name="date_from" value="<?= esc($filters['date_from']) ?>" placeholder="From dd-mm-yyyy" aria-label="Notification date from"><input class="form-control form-control-sm patient-date-filter" type="text" name="date_to" value="<?= esc($filters['date_to']) ?>" placeholder="To dd-mm-yyyy" aria-label="Notification date to"><select class="form-control form-control-sm" name="page_size" aria-label="Page size"><?php foreach ([10, 15, 25, 50] as $size): ?><option value="<?= $size ?>" <?= (int) $filters['page_size'] === $size ? 'selected' : '' ?>><?= $size ?> / page</option><?php endforeach; ?></select><div class="patient-filter-actions"><button class="btn btn-primary btn-sm" type="submit"><i class="bi bi-funnel mr-1" aria-hidden="true"></i>Apply</button><a class="btn btn-light btn-sm" href="<?= current_url() ?>">Clear</a></div></form></section>
    <section class="card patient-notifications-content"><div class="card-header d-flex flex-wrap align-items-center justify-content-between"><div><h2 class="h5 mb-1">Notification inbox</h2><span class="small text-muted">Only updates belonging to your account are shown.</span></div><button class="btn btn-sm btn-outline-primary" type="button" id="patient-mark-all-read" <?= (int) $unread === 0 ? 'disabled' : '' ?>><i class="bi bi-check2-all mr-1" aria-hidden="true"></i>Mark all as read</button></div><?php if ($notifications === []): ?><div class="patient-empty-state"><i class="bi bi-bell-slash" aria-hidden="true"></i><strong>No notifications found</strong><span>New clinic updates will appear here.</span></div><?php else: ?><div class="patient-notification-list"><?php foreach ($notifications as $notification): ?><article class="patient-notification-row <?= ($notification['status'] ?? '') === 'unread' ? 'is-unread' : '' ?>" data-notification-id="<?= (int) $notification['id'] ?>"><div class="patient-notification-icon" aria-hidden="true"><i class="bi <?= ($notification['status'] ?? '') === 'unread' ? 'bi-bell-fill' : 'bi-bell' ?>"></i></div><div class="patient-notification-content"><div class="patient-notification-heading"><h3><?= esc($notification['title'] ?? 'Notification') ?></h3><span class="badge patient-status-badge <?= ($notification['status'] ?? '') === 'unread' ? 'patient-status-unread' : 'patient-status-read' ?>"><?= esc(ucfirst($notification['status'] ?? 'read')) ?></span></div><p><?= nl2br(esc($notification['message'] ?? '')) ?></p><div class="patient-notification-meta"><span><i class="fa-solid fa-circle-exclamation mr-1" aria-hidden="true"></i><?= esc($notification['created_display'] ?? 'Not recorded') ?></span><span><?= esc($notification['related_label'] ?? 'Notification') ?></span></div></div><div class="patient-notification-actions"><button class="btn btn-sm btn-outline-primary patient-notification-view" type="button" data-id="<?= (int) $notification['id'] ?>" data-toggle="modal" data-target="#patient-notification-detail-modal">View</button><?php if (($notification['status'] ?? '') === 'unread'): ?><button class="btn btn-sm btn-light patient-notification-read" type="button" data-id="<?= (int) $notification['id'] ?>">Mark read</button><?php endif; ?><?php if (! empty($notification['related_url'])): ?><a class="btn btn-sm btn-link" href="<?= esc($notification['related_url']) ?>">Open related</a><?php endif; ?></div></article><?php endforeach; ?></div><?php endif; ?></section>
    <?php $values = ['search' => $filters['search'], 'status' => $filters['status'], 'type' => $filters['type'], 'date_from' => $filters['date_from'], 'date_to' => $filters['date_to'], 'page_size' => $filters['page_size']]; ?><div class="card pagination-card mb-4"><div class="card-body py-3 d-flex flex-wrap align-items-center justify-content-between"><span class="small text-muted">Showing page <?= (int) $pagination['page'] ?> of <?= (int) $pagination['pages'] ?> · <?= (int) $pagination['total'] ?> notifications</span><nav aria-label="Notification pagination"><?php $values['page'] = max(1, (int) $pagination['page'] - 1); ?><a class="btn btn-sm btn-outline-secondary <?= (int) $pagination['page'] <= 1 ? 'disabled' : '' ?>" href="<?= (int) $pagination['page'] > 1 ? esc(current_url() . '?' . http_build_query($values)) : '#' ?>">Previous</a><?php $values['page'] = min((int) $pagination['pages'], (int) $pagination['page'] + 1); ?><a class="btn btn-sm btn-outline-secondary <?= (int) $pagination['page'] >= (int) $pagination['pages'] ? 'disabled' : '' ?>" href="<?= (int) $pagination['page'] < (int) $pagination['pages'] ? esc(current_url() . '?' . http_build_query($values)) : '#' ?>">Next</a></nav></div></div>
    <div class="modal fade patient-notification-modal" id="patient-notification-detail-modal" tabindex="-1" role="dialog" aria-labelledby="patient-notification-detail-title" aria-hidden="true"><div class="modal-dialog modal-dialog-scrollable" role="document"><div class="modal-content"><div class="modal-header"><div><span class="patient-eyebrow">Patient-safe notification</span><h2 class="modal-title h5" id="patient-notification-detail-title">Notification Details</h2></div><button class="close" type="button" data-dismiss="modal" aria-label="Close"><span aria-hidden="true">&times;</span></button></div><div class="modal-body" id="patient-notification-detail-body" aria-live="polite"><div class="patient-modal-loading" role="status"><span class="spinner-border spinner-border-sm mr-2" aria-hidden="true"></span>Loading notification details…</div></div><div class="modal-footer"><button class="btn btn-light" type="button" data-dismiss="modal">Close</button></div></div></div></div>
</main>
<?= $this->endSection() ?>

<?= $this->section('scripts') ?><script>
    $(function () {
        var records = <?= json_encode($notifications, JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_AMP | JSON_HEX_QUOT) ?>;
        var escapeHtml = function (value) { return $('<div>').text(value == null ? '' : value).html(); };
        $('.patient-date-filter').datepicker({ format: 'dd-mm-yyyy', autoclose: true, todayHighlight: true, orientation: 'bottom auto', container: '.patient-notifications-page' });
        var refreshUnread = function () { $.getJSON('<?= base_url('patient/notifications/unread-count') ?>').done(function (response) { if (response.status) $('#patient-unread-count').text(response.unread); }); };
        var markRead = function (id, button) { button.prop('disabled', true); ajaxRequest({ url: '<?= base_url('patient/notifications') ?>/' + Number(id) + '/read', data: { '<?= csrf_token() ?>': '<?= csrf_hash() ?>' }, success: function (response) { if (response.status) { showSuccess(response.msg); button.closest('.patient-notification-row').removeClass('is-unread').find('.patient-status-unread').removeClass('patient-status-unread').addClass('patient-status-read').text('Read'); button.closest('.patient-notification-row').find('.patient-notification-read').remove(); refreshUnread(); } else showError(response.msg); }, complete: function () { button.prop('disabled', false); } }); };
        $(document).on('click.patientNotificationRead', '.patient-notification-read', function () { markRead($(this).data('id'), $(this)); });
        $('#patient-mark-all-read').on('click', function () { var button = $(this); button.prop('disabled', true); ajaxRequest({ url: '<?= base_url('patient/notifications/read-all') ?>', data: { '<?= csrf_token() ?>': '<?= csrf_hash() ?>' }, success: function (response) { if (response.status) { showSuccess(response.msg); $('.patient-notification-row').removeClass('is-unread'); $('.patient-status-unread').removeClass('patient-status-unread').addClass('patient-status-read').text('Read'); $('.patient-notification-read').remove(); $('#patient-unread-count').text('0'); } else showError(response.msg); }, complete: function () { button.prop('disabled', false); } }); });
        $(document).on('click.patientNotificationView', '.patient-notification-view', function () { var notification = records.find(function (item) { return Number(item.id) === Number($(this).data('id')); }.bind(this)); var body = $('#patient-notification-detail-body'); body.html('<div class="patient-modal-loading" role="status"><span class="spinner-border spinner-border-sm mr-2" aria-hidden="true"></span>Loading notification details…</div>'); if (! notification) { body.html('<div class="patient-modal-state patient-modal-state-error" role="alert">Notification details could not be found.</div>'); return; } $('#patient-notification-detail-title').text(notification.title || 'Notification Details'); body.html('<section class="patient-modal-section"><h3><i class="bi bi-bell mr-2" aria-hidden="true"></i>' + escapeHtml(notification.related_label || 'Notification') + '</h3><p class="mb-2">' + escapeHtml(notification.message || '') + '</p><p class="patient-modal-metadata"><i class="fa-solid fa-circle-exclamation mr-1" aria-hidden="true"></i>' + escapeHtml(notification.created_display || 'Not recorded') + ' · ' + escapeHtml(notification.status || 'read') + '</p></section>' + (notification.related_url ? '<a class="btn btn-primary" href="' + escapeHtml(notification.related_url) + '">Open related record</a>' : '')); });
    });
</script><?= $this->endSection() ?>
